:root {
  color-scheme: light dark;
  --bg: #f6f7f9;
  --surface: #ffffff;
  --text: #16191d;
  --muted: #5a6472;
  --line: #d7dce3;
  --accent: #0f766e;
  --accent-soft: #e6f2f0;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #14171c;
    --surface: #1c2027;
    --text: #eef1f5;
    --muted: #a3adba;
    --line: #333a45;
    --accent: #5eead4;
    --accent-soft: #16302e;
  }
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font: 16px/1.55 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}

#app {
  max-width: 44rem;
  margin: 0 auto;
  padding: 1.5rem 1rem 4rem;
}

.page-header h1 {
  margin: 0;
  font-size: 1.9rem;
  letter-spacing: -0.02em;
}

.tagline {
  margin: 0.25rem 0 1.5rem;
  color: var(--muted);
}

h2 {
  font-size: 1.05rem;
  margin: 0 0 0.75rem;
}

#note-form,
.search {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 1rem;
  margin-bottom: 1.25rem;
}

.field {
  margin-bottom: 0.85rem;
}

label {
  display: block;
  font-size: 0.85rem;
  font-weight: 600;
  margin-bottom: 0.3rem;
}

.optional {
  font-weight: 400;
  color: var(--muted);
}

input,
textarea {
  width: 100%;
  padding: 0.5rem 0.6rem;
  font: inherit;
  color: inherit;
  background: var(--bg);
  border: 1px solid var(--line);
  border-radius: 7px;
}

textarea {
  resize: vertical;
  min-height: 5rem;
}

.hint {
  margin: 0.35rem 0 0;
  font-size: 0.8rem;
  color: var(--muted);
}

button {
  font: inherit;
  cursor: pointer;
}

button.primary {
  background: var(--accent);
  color: #ffffff;
  border: 1px solid transparent;
  border-radius: 7px;
  padding: 0.5rem 1rem;
  font-weight: 600;
}

@media (prefers-color-scheme: dark) {
  button.primary {
    color: #06231f;
  }
}

:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

#results-line {
  margin: 0.5rem 0 0;
  color: var(--muted);
  font-size: 0.9rem;
  min-height: 1.4em;
}

#results-line:empty {
  min-height: 0;
}

#empty-state {
  color: var(--muted);
  background: var(--surface);
  border: 1px dashed var(--line);
  border-radius: 10px;
  padding: 1rem;
}

#feed {
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
}

.note {
  background: var(--surface);
  border: 1px solid var(--line);
  border-left: 4px solid transparent;
  border-radius: 10px;
